-- Issue #88. Apply explicitly before enabling the project skill picker.
-- Existing skill XP codes are reused; IDs are generated by PostgreSQL.
BEGIN;
CREATE TABLE IF NOT EXISTS recruit_skills (
    skill_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    skill_code VARCHAR(64) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL
);
INSERT INTO recruit_skills (skill_code, name) VALUES
    ('PYTHON', 'Python'), ('SQL', 'SQL'), ('GIT', 'Git/GitHub'),
    ('REACT', 'React'), ('LANGCHAIN', 'LangChain')
ON CONFLICT (skill_code) DO NOTHING;
COMMIT;
